using PklGenerator.Declaration;

namespace PklGenerator.Tests.Declaration;

public class EnumDeclarationTests
{
    [Fact]
    public void EnumDeclarationGeneratesCorrectSourceCode()
    {
        var expectedSource = """
                             // <auto-generated />
                             #nullable enable
                             namespace TestNamespace;

                             public enum EnumType
                             {
                                 Member1,
                                 Member2,
                             }

                             """;
        
        var testEnum = new EnumDeclaration("EnumType", "TestNamespace");
        testEnum.AddMember("Member1");
        testEnum.AddMember("Member2");

        var sourceText = testEnum.ToSourceText();
        
        Assert.Equal(expectedSource, sourceText.ToString());
    }

    [Fact]
    public void StringUnionEnumsCarryTheirPklValues()
    {
        var expectedSource = """
                             // <auto-generated />
                             #nullable enable
                             namespace TestNamespace;

                             [global::Pkl.PklStringUnion]
                             public enum Status
                             {
                                 [global::Pkl.PklStringUnionValue("in-progress")]
                                 InProgress,
                                 [global::Pkl.PklStringUnionValue("say \"hi\"")]
                                 SayHi,
                             }

                             """;

        var testEnum = new EnumDeclaration("Status", "TestNamespace") { IsStringUnion = true };
        testEnum.AddMember("InProgress", "in-progress");
        testEnum.AddMember("SayHi", "say \"hi\"");

        Assert.Equal(expectedSource, testEnum.ToSourceText().ToString());
    }
}
